SELECT 'v' AS k, v.tender_id, v.seq, v.published_at, v.notice_subtype, v.caused_by_notice_id, v.publication_id, NULL AS a, NULL AS b, NULL AS c FROM tender_versions v WHERE v.tender_id = 878700 AND v.seq BETWEEN 358 AND 362 UNION ALL SELECT 'v', v.tender_id, v.seq, v.published_at, v.notice_subtype, v.caused_by_notice_id, v.publication_id, NULL, NULL, NULL FROM tender_versions v WHERE v.tender_id = 1139127 AND v.seq BETWEEN 1 AND 5 UNION ALL SELECT 't', t.id, t.current_seq, t.current_published_at, t.source, t.current_value_eur_cents, t.current_value_currency, t.current_value_cents, t.current_value_derivation, t.projection_epoch FROM tenders t WHERE t.id = 878700 UNION ALL SELECT 't', t.id, t.current_seq, t.current_published_at, t.source, t.current_value_eur_cents, t.current_value_currency, t.current_value_cents, t.current_value_derivation, t.projection_epoch FROM tenders t WHERE t.id = 1139127 
